// Build Gemini image-edit request from the incoming Telegram photo
const bin = items[0].binary.data;
return [{ json: { body: {
  contents: [{ parts: [
    { inlineData: { mimeType: bin.mimeType || 'image/jpeg', data: bin.data } },
    { text: 'Re-render this jewellery as a professional luxury studio product photograph: elegant premium backdrop, soft key lighting, crisp focus on the jewellery, realistic, no added text or people.' }
  ]}],
  generationConfig: { responseModalities: ['TEXT','IMAGE'] }
} } , binary: items[0].binary }];

// Extract the generated image (base64) into n8n binary
const parts = $json.candidates?.[0]?.content?.parts || [];
const img = parts.find(p => p.inlineData);
if (!img) throw new Error('Gemini returned no image');
return [{ json: { caption: 'New design ✨' }, binary: { photo: { data: img.inlineData.data, mimeType: img.inlineData.mimeType || 'image/png', fileName: 'studio.png' } } }];
